<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Attributes\Fillable; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
#[Fillable(['receipt_number','payment_id','invoice_id','customer_id','receipt_date','invoice_total_snapshot','previously_paid_snapshot','payment_amount_snapshot','balance_amount_snapshot','payment_mode_snapshot','transaction_reference_snapshot','customer_name_snapshot','customer_mobile_snapshot','customer_address_snapshot','customer_email_snapshot','agency_name_snapshot','agency_address_snapshot','agency_phone_snapshot','agency_email_snapshot','agency_gst_snapshot','bank_holder_snapshot','bank_name_snapshot','bank_ifsc_snapshot','upi_id_snapshot','authorized_person_snapshot','signature_path_snapshot','stamp_path_snapshot','notes_snapshot','pdf_path','pdf_generated_at','pdf_version','created_by'])]
class PaymentReceipt extends Model { public function payment():BelongsTo{return $this->belongsTo(Payment::class);} public function invoice():BelongsTo{return $this->belongsTo(Invoice::class);} public function customer():BelongsTo{return $this->belongsTo(Customer::class);} protected function casts():array{return ['receipt_date'=>'date','pdf_generated_at'=>'datetime','invoice_total_snapshot'=>'decimal:2','previously_paid_snapshot'=>'decimal:2','payment_amount_snapshot'=>'decimal:2','balance_amount_snapshot'=>'decimal:2'];} }
